/** Geometry must not be rebuilt underneath WebKit's native touch pan. A
 * pointercancel means the browser took the gesture, not that the finger lifted.
 * Keep the last measured scene through the whole touch and its scroll inertia;
 * coalesce toolbar/font/image/observer changes once the page has settled. */
export function createScrollLayoutScheduler(layout:()=>void, quiet=200) {
 let live=true,touching=false,dirty=false,frame=0,timer=0,lastActivity=-Infinity;
 const cancel=()=>{cancelAnimationFrame(frame);clearTimeout(timer);frame=timer=0;};
 const flush=()=>{
  frame=timer=0;if(!live||!dirty||touching)return;
  const remaining=quiet-(performance.now()-lastActivity);
  if(remaining>0){timer=window.setTimeout(flush,remaining);return;}
  dirty=false;layout();
 };
 const request=()=>{if(!live)return;dirty=true;if(touching)return;if(!frame&&!timer)frame=requestAnimationFrame(flush);};
 const activity=()=>{lastActivity=performance.now();if(timer){clearTimeout(timer);timer=0;}if(dirty&&!touching)request();};
 const start=()=>{touching=true;activity();cancel();};
 const end=(event:TouchEvent)=>{if(event.touches.length)return;touching=false;activity();if(dirty)request();};
 const blur=()=>{touching=false;activity();if(dirty)request();};
 document.addEventListener('touchstart',start,{passive:true});
 document.addEventListener('touchmove',activity,{passive:true});
 document.addEventListener('touchend',end,{passive:true});
 document.addEventListener('touchcancel',end,{passive:true});
 window.addEventListener('scroll',activity,{passive:true});
 window.addEventListener('blur',blur);
 return {request,dispose:()=>{
  live=false;cancel();document.removeEventListener('touchstart',start);document.removeEventListener('touchmove',activity);
  document.removeEventListener('touchend',end);document.removeEventListener('touchcancel',end);
  window.removeEventListener('scroll',activity);window.removeEventListener('blur',blur);
 }};
}

export type RailGestureAnchor={progress:number;natural:number};
/** A horizontal swipe edits only the row, never window.scrollY. Subsequent
 * vertical scrolling joins the same position continuously and still reaches
 * both ends of the original runway, so it cannot trap page navigation. */
export function railProgress(natural:number,distance:number,anchor?:RailGestureAnchor) {
 const n=Math.max(0,Math.min(distance,natural));
 if(!anchor)return n;
 if(n===anchor.natural)return anchor.progress;
 if(n<anchor.natural)return anchor.progress*n/Math.max(1,anchor.natural);
 return anchor.progress+(distance-anchor.progress)*(n-anchor.natural)/Math.max(1,distance-anchor.natural);
}

import { useEffect, type RefObject } from 'react';

const SURFACES = 'main, section, header, footer, .m-dark, .m-home-field, .m10-home-caption, .m-earth-coda, .m-closing, .m-offer';

/** Browser chrome is browser-owned. Supply the visible surface as a tint hint
 * and as the document underlay used by translucent UI and rubber-band areas. */
export function useMobileBrowserTheme(root: RefObject<HTMLElement>, routeKey: string) {
  useEffect(() => {
    const host = root.current;
    if (!host) return;
    const existingMeta = document.querySelector<HTMLMetaElement>('meta[name="theme-color"]');
    const meta = existingMeta ?? document.createElement('meta');
    const previousMeta = meta.getAttribute('content');
    if (!existingMeta) {
      meta.name = 'theme-color';
      document.head.appendChild(meta);
    }
    const underlays = [document.documentElement, document.body];
    const previousColors = underlays.map(element => ({
      value: element.style.getPropertyValue('background-color'),
      priority: element.style.getPropertyPriority('background-color'),
    }));
    let observer: IntersectionObserver | undefined;
    let frame = 0;
    let resizeTimer = 0;
    let active = true;
    let lastColor = '';

    const visibleColor = () => {
      // Sample the margin, not the photo or card occupying the page centre.
      // Transparencies inherit the first opaque surface beneath them.
      const y = Math.min(window.innerHeight - 1, Math.max(1, (window.visualViewport?.offsetTop ?? 0) + 2));
      const candidates = document.elementsFromPoint(Math.min(12, window.innerWidth / 4), y);
      for (const candidate of candidates) {
        if (!host.contains(candidate) || candidate.closest('.m-dock')) continue;
        let element: Element | null = candidate;
        while (element && host.contains(element)) {
          // These complete surfaces are painted on a masked ::before layer.
          // Other pseudo-elements are only decorative edges, not backgrounds.
          const paintLayer = element.matches('.m-offer, .m-earth-coda') ? '::before' : null;
          const color = getComputedStyle(element, paintLayer).backgroundColor;
          const channels = color.match(/[\d.]+/g)?.map(Number);
          if (channels && channels.length >= 3 && (channels.length < 4 || channels[3] >= 0.98)) return color;
          element = element.parentElement;
        }
      }
      return getComputedStyle(host).backgroundColor || '#E5D8C4';
    };
    const update = () => {
      frame = 0;
      if (!active) return;
      const color = visibleColor();
      if (color === lastColor) return;
      lastColor = color;
      meta.content = color;
      underlays.forEach(element => { element.style.backgroundColor = color; });
    };
    const schedule = () => { if (!frame && active) frame = requestAnimationFrame(update); };
    const observe = () => {
      if (!active) return;
      observer?.disconnect();
      // Observe a thin strip at the visible top edge. Work happens at section
      // boundaries, never on each touch/scroll frame or in a polling loop.
      const top = Math.min(window.innerHeight - 2, Math.max(0, window.visualViewport?.offsetTop ?? 0));
      observer = new IntersectionObserver(schedule, {
        rootMargin: `-${top}px 0px -${Math.max(0, window.innerHeight - top - 8)}px 0px`,
        threshold: 0,
      });
      observer.observe(host);
      host.querySelectorAll(SURFACES).forEach(element => observer?.observe(element));
      schedule();
    };
    const resize = () => {
      clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(observe, 180);
    };
    observe();
    window.addEventListener('resize', resize, { passive: true });
    window.visualViewport?.addEventListener('resize', resize, { passive: true });
    window.addEventListener('pageshow', schedule);
    document.fonts.ready.then(() => { if (active) schedule(); });
    return () => {
      active = false;
      observer?.disconnect();
      cancelAnimationFrame(frame);
      clearTimeout(resizeTimer);
      window.removeEventListener('resize', resize);
      window.visualViewport?.removeEventListener('resize', resize);
      window.removeEventListener('pageshow', schedule);
      underlays.forEach((element, index) => {
        const previous = previousColors[index];
        if (previous.value) element.style.setProperty('background-color', previous.value, previous.priority);
        else element.style.removeProperty('background-color');
      });
      if (!existingMeta) meta.remove();
      else if (previousMeta === null) meta.removeAttribute('content');
      else meta.content = previousMeta;
    };
  }, [root, routeKey]);
}

